(function(){
  'use strict';
  const R=window.OrchardRates,M=window.OrchardMeta,G=window.OrchardGuidance;
  const refs=[['book',27,'MeRSIA proposal; this is a new bounded resource experiment'],['alignment',3,'Charged resources and improvement criteria'],['enquiry',7,'§10.2, proposed stronger developmental test']];
  G.registerDefinitions({
    logicalwork:{title:'Charged logical work',aliases:['logical-work index','charged logical work'],plain:'A declared cost model for specified learning and checking operations. It lets us compare budget prefixes without pretending to measure all computation.',math:'r=P_fit+w_v P_validation+w_p(N_preservation+N_truth)+P_replay_fit+w_v P_replay_validation. Display w_v,w_p∈{1,2,4}. Host overhead, data generation, memory, wall time and evaluation costs are excluded; this is a sensitivity model, not a hardware benchmark.',refs},
    learningcurve:{title:'Resource-prefix learning curve',aliases:['learning curve','resource-prefix curve'],plain:'Show when an expression becomes available as its declared acquisition work is paid. Before that point, use remains withheld.',math:'Available_i(r)=1 iff the pipeline completed its required phases and r≥threshold_i. Frozen response accuracy is shown only once an expression is available. With valid B evidence and unit weights, fit-only threshold=2,068; checked threshold=8,792. This is one conditional subsequent-learning task, not a universal rate law.',refs},
    fitbaseline:{title:'Fit-only learning baseline',aliases:['fit-only baseline','fit-only learner'],plain:'A conventional learner selects the unique expression matching all teaching answers in the same expanded language. It does not enforce the laboratory’s additional trust, preservation, validation or replay obligations.',math:'Search all 47 G₁ programs on the same 44 B measurements. Require one survivor; pay 47·44 prediction units. Use the candidate for separate response scoring. A fitted expression is not a receiving grant or a qualified adoption.',refs},
    checkedadoption:{title:'Checked expression adoption',aliases:['checked adoption','checked learner'],plain:'An expression is retained only after the declared feedback, preserved meanings, separate validation and replay checks pass.',math:'Require current trusted D/V, matching task contracts, 312 protected meanings, four Boolean rows, unique full selection, 2,170 validation answers and actual repair replay. Unit costs: 316+2,068+2,170+(2,068+2,170)=8,792. Learning permission and runtime receiving authority remain distinct.',refs},
    responsecensus:{title:'Frozen response evaluation',aliases:['response evaluation'],plain:'Test the frozen candidate’s response predictions in a larger finite context. This measures response fidelity, not general safety or authority to act.',math:'At n=7, c∈{3,4}, enumerate 70 K and 126 proper queries each: 8,820 response checks. Scoring does not revise either learner. Fixtures were inspected during development; this is not independent replication or an unbounded generalization result.',refs},
    evidencecoverage:{title:'Declared evidence coverage',aliases:['evidence checklist','evidence coverage'],plain:'The fraction of explicit laboratory checklist entries that have supporting evidence. It is not the percentage of MeRSIA achieved.',math:'Each of six stages has seven visible evidence gates. In this version, contracts, mathematical models, finite tests and native-Python parity are evidenced; independent robustness, measured scale-up and generalized application are not. 24/42=57%. Gates have unequal difficulty and are not a probability of success.',refs}
  });
  function run(input){if(!input||input.protocol!=='orchard-lab/1')throw Error('Unsupported laboratory protocol.');const p=input.previous;if(p){if(p.protocol!=='orchard-lab/1'||p.experiment!=='bounded-meta-extension'||!p.passed||p.authorityExpanded!==false)throw Error('Stage six requires the checked stage-five constructor.');M.restoreMethod(p.generatorArtifact);}const s=R.compare(),bad=R.compare({kind:'wrong-teaching'});return {protocol:'orchard-lab/1',experiment:'resource-comparison',passed:s.arms[0].threshold===2068&&s.arms[1].threshold===8792&&s.arms.every(a=>a.score.correct===8820)&&bad.arms[1].threshold===null,summary:'Matched 47-program later learning: fit-only availability at 2,068 declared work units; checked adoption at 8,792. Both valid frozen candidates pass 8,820 response checks. Wrong teaching fails checked validation. Added safeguards cost work; no faster alignment development or full MeRSIA claim is established.',previousConsumed:!!p,transfer:p?'qualified-constructor':'none',runtimeEvidenceTransfer:'none',authorityExpanded:false,metaGrammarExpanded:false,relativeRateDominanceEstablished:false,resourceModel:'declared-logical-work/1',comparison:s.arms};}
  function mount({container}){
    const abort=new AbortController();let study=R.compare(),budget=8792;
    container.innerHTML=`<section class="intro"><div><div class="chapter">Encounter 06 · A first resource comparison</div><h1>What Does Better Checking Cost?</h1><p>Give two learners the same candidate language and teaching task. Price their actual learning and checking phases, test the frozen result, and see what survives faulty feedback.</p></div><div class="intro-note">A defined work model.<br>A matched fitting baseline.<br>An honest rate result.</div></section>
    <section class="guided-path"><div class="guide-top"><span class="chapter">Towards a rate test</span><span class="helper">Different adoption obligations; the same response task.</span></div><h2>A measurable beginning for stage six</h2><p>The fit-only baseline learns a matching expression. The checked learner additionally requires current trusted feedback, preservation, separate validation and replay. Both start with the same admitted OR-pair language. This tests the cost of stronger adoption requirements; it does not yet compare general alignment development with all other capability growth.</p><p>The curves reconstruct a budget prefix from a computed phase ledger. They do not measure wall time or suspend a physical process. Frozen response evaluation stays outside acquisition.</p></section>
    <div class="workspace"><aside class="controls enquiry-controls"><h2>Set the comparison</h2><label class="field">Teaching / checking condition<select id="rate-case"><option value="valid">Valid, current teaching</option><option value="wrong-teaching">A answers mislabeled as Task B teaching</option><option value="untrusted">Untrusted teaching source</option><option value="stale">Changed teaching source version</option><option value="bad-validation">One corrupt validation answer</option><option value="drop-old">Constructor deletes an old program</option></select></label><label class="field">Validation prediction weight<select id="rate-validation"><option>1</option><option>2</option><option>4</option></select></label><label class="field">Preservation / truth check weight<select id="rate-preservation" aria-label="Preservation / truth check weight"><option>1</option><option>2</option><option>4</option></select></label><label class="checkbox-line"><input id="rate-common" type="checkbox">Charge shared source-method acquisition to both arms</label><p class="helper">Weights price declared logical checks, not instruction counts or elapsed seconds. Source construction is shared scaffolding for this matched later task.</p><button id="rate-reset" class="secondary wide-button">Reset comparison</button><button id="rate-glossary" class="quiet wide-button">Browse all definitions</button></aside><div>
    <div class="metrics"><div class="metric"><div class="metric-name">Fit-only availability</div><div id="rate-fit-cost" class="metric-value"></div><div class="metric-detail">Declared work threshold</div></div><div class="metric"><div class="metric-name">Checked adoption</div><div id="rate-checked-cost" class="metric-value"></div><div class="metric-detail">Declared work threshold or hold</div></div><div class="metric"><div class="metric-name">Evaluation scope</div><div class="metric-value">8,820</div><div class="metric-detail">Frozen response checks per candidate</div></div></div>
    <section class="panel"><h2>Follow learning through its resource envelope</h2><label class="field">Declared acquisition budget <strong id="rate-budget-value"></strong><input type="range" id="rate-budget" min="0" max="12000" step="1" value="8792" style="width:100%;margin-top:16px"></label><div class="execution-controls"><button id="rate-zero" class="quiet">Zero budget</button><button id="rate-at-fit" class="secondary">At fit-only threshold</button><button id="rate-at-checked" class="secondary">At checked threshold</button></div><div id="rate-plot"></div><div class="plot-legend"><span><i class="legend-line"></i>Fit-only model available</span><span><i class="legend-line action-line"></i>Checked model available</span></div><div id="rate-prefix" class="state-explanation" aria-live="polite"></div><p id="rate-common-note"></p></section>
    <section class="panel evidence-panel"><h2>Price the actual phases</h2><div id="rate-ledger" class="table-wrap"></div><p id="rate-excluded"></p><p>Replay is an actual re-run of the candidate’s fitting and validation checks. A failed phase cannot be replaced by a larger budget. Feedback/scope and host equality checks are required but unpriced in this declared index.</p></section>
    <section class="panel evidence-panel"><h2>Evaluate the frozen expression</h2><div id="rate-evaluation"></div><p>Both models face the same 8,820 Task B response questions at n=7/c=3,4. A hold has no installed candidate to score. A response-fidelity result is not a receiving action or a general alignment score.</p></section></div></div>
    <section class="panel evidence-panel"><h2>What would make this a stronger MeRSIA test?</h2><p>Specify an alignment invariant and a separate capability-development objective. Use repeated new tasks, a common comprehensive resource measure, strong preinstalled and adaptive comparators, and tests outside the development fixtures. Measure slopes, uncertainty and regressions before claiming that alignment development outpaces other growth.</p><p id="rate-conclusion"></p><a href="downloads/06_resource_comparison_source.html" target="_blank" rel="noopener">Inspect the native Python experiment</a> · <a href="downloads/06_resource_comparison.py" download>Download the self-contained script</a></section>`;
    const q=id=>container.querySelector('#'+id),on=(id,event,fn)=>q(id).addEventListener(event,fn,{signal:abort.signal});
    function render(){const [f,c]=study.arms,max=Math.max(12000,...study.arms.map(a=>a.chargedWork))*1.15;q('rate-budget').max=String(Math.ceil(max));budget=Math.min(budget,Number(q('rate-budget').max));q('rate-budget').value=String(budget);q('rate-budget-value').textContent=budget.toLocaleString();q('rate-fit-cost').textContent=f.threshold===null?'Hold':f.threshold.toLocaleString();q('rate-checked-cost').textContent=c.threshold===null?'Hold':c.threshold.toLocaleString();q('rate-at-fit').disabled=f.threshold===null;q('rate-at-checked').disabled=c.threshold===null;
      const sx=r=>42+300*r/max,thresholdLine=(a,color,dash)=>{if(a.threshold===null)return `<line x1="42" x2="342" y1="152" y2="152" stroke="${color}" stroke-width="3" ${dash}/>`;const x=sx(a.threshold);return `<polyline points="42,152 ${x},152 ${x},42 342,42" fill="none" stroke="${color}" stroke-width="3" ${dash}/><text x="${x}" y="186" text-anchor="middle">${a.threshold.toLocaleString()}</text>`;};q('rate-plot').innerHTML=`<svg class="frontier-svg" viewBox="0 0 390 230" role="img" aria-label="Model availability by declared work: fit-only ${f.threshold}, checked ${c.threshold}; selected budget ${budget}"><title>Resource-prefix availability</title><line x1="42" x2="342" y1="152" y2="152" stroke="#ccd7e1"/><line x1="42" x2="342" y1="42" y2="42" stroke="#ccd7e1"/><text x="28" y="157">0</text><text x="28" y="47">1</text>${thresholdLine(f,'#2359af','')}${thresholdLine(c,'#087859','stroke-dasharray="7 5"')}<line x1="${sx(budget)}" x2="${sx(budget)}" y1="25" y2="158" stroke="#ac4b13"/><text x="42" y="212">Declared acquisition work →</text><text x="42" y="20">Vertical: model available, 0 or 1</text></svg>`;
      const prefix=R.atBudget(study,budget);q('rate-prefix').innerHTML=prefix.map(a=>`<p><strong>${a.arm==='checked'?'Checked learner':'Fit-only learner'}: ${a.available?'model available':'held / unavailable'}</strong>${a.available?'Frozen response fidelity: '+(100*a.accuracy).toFixed(1)+'%.':'Reason: '+a.reason+'.'}</p>`).join('');q('rate-common-note').textContent='Shared source-method acquisition: '+study.commonWork.toLocaleString()+' declared units; '+(study.includeCommon?'charged equally to both arms.':'shown separately, excluded from these conditional later-learning curves.');
      q('rate-ledger').innerHTML=`<table class="inspector-table"><thead><tr><th>Phase counts (weights shown above)</th><th>Fit-only</th><th>Checked</th></tr></thead><tbody>${[['Candidate response predictions','selection'],['Separate validation predictions','validation'],['Protected old-meaning checks','preservation'],['Boolean truth rows','truth'],['Replay fit predictions','replaySelection'],['Replay validation predictions','replayValidation'],['Priced later-learning work','work']].map(([label,key])=>`<tr><td>${label}</td><td>${f[key].toLocaleString()}</td><td>${c[key].toLocaleString()}</td></tr>`).join('')}</tbody></table>`;q('rate-excluded').textContent=study.excluded;
      q('rate-evaluation').innerHTML=study.arms.map(a=>`<div class="census-row"><strong>${a.arm==='checked'?'Checked learner':'Fit-only learner'} · ${a.status}</strong>${a.score?`<div class="census-bar"><span class="correct-segment" style="width:${100*a.score.accuracy}%"></span><span class="incorrect-segment" style="width:${100*(1-a.score.accuracy)}%"></span></div><small>${a.score.correct.toLocaleString()}/${a.score.total.toLocaleString()} correct responses. Scoring never changes the candidate.</small>`:`<p>No adopted model. Reason: ${a.reason}.</p>`}</div>`).join('');q('rate-conclusion').textContent=study.rateClaim;G.annotate(container);
    }
    function update(){study=R.compare({kind:q('rate-case').value,validationWeight:Number(q('rate-validation').value),preservationWeight:Number(q('rate-preservation').value),includeCommon:q('rate-common').checked});render();}
    for(const id of ['rate-case','rate-validation','rate-preservation','rate-common'])on(id,'change',update);on('rate-budget','input',()=>{budget=Number(q('rate-budget').value);render();});on('rate-zero','click',()=>{budget=0;render();});on('rate-at-fit','click',()=>{budget=study.arms[0].threshold;render();});on('rate-at-checked','click',()=>{budget=study.arms[1].threshold;render();});on('rate-reset','click',()=>{q('rate-case').value='valid';q('rate-validation').value='1';q('rate-preservation').value='1';q('rate-common').checked=false;budget=8792;update();});on('rate-glossary','click',()=>G.showGlossary());render();return {dispose(){abort.abort();},snapshot(){return {study,budget,prefix:R.atBudget(study,budget)};}};
  }
  window.OrchardLab.register({id:'resource-comparison',title:'06 · What Does Better Checking Cost?',version:'0.6.0',contractVersion:1,mount,run});
})();
